export const INTENTS=Object.freeze({NAVIGATE:"NAVIGATE",BOOKMARK:"BOOKMARK",SEARCH:"SEARCH",ITINERARY:"ITINERARY",LANGUAGE_SWITCH:"LANGUAGE_SWITCH",QA_FALLBACK:"QA_FALLBACK"});export const NAVIGATION_ROUTES=Object.freeze({home:"/",cuisine:"/frontend/cuisine/cuisine.html",festivals:"/frontend/festivals/festivals.html",culture:"/frontend/culture/culture.html",wildlife:"/frontend/wildlife/wildlife.html",monuments:"/frontend/monuments/monuments.html",travel:"/frontend/travel/travel.html","route planner":"/frontend/route-planner/route-planner.html","trip planner":"/frontend/travel/travel.html"});export const VOICE_LANGUAGES=Object.freeze({english:"en",hindi:"hi",bengali:"bn",tamil:"ta",telugu:"te",marathi:"mr",gujarati:"gu",kannada:"kn",malayalam:"ml",punjabi:"pa",urdu:"ur"});function includesAny(t,e){return e.some(e=>t.includes(e))}function findNavigationTarget(t){for(const e of Object.keys(NAVIGATION_ROUTES))if(t.includes(e))return{key:e,path:NAVIGATION_ROUTES[e]};return null}function findLanguageTarget(t){for(const e of Object.keys(VOICE_LANGUAGES))if(t.includes(e))return{name:e,code:VOICE_LANGUAGES[e]};return null}function extractAfter(t,e){for(const n of e){const e=t.indexOf(n);if(-1!==e){const r=t.slice(e+n.length).trim();if(r)return r}}return null}function extractDays(t){const e=t.match(/(\d+)\s*[- ]?day/);return e?parseInt(e[1],10):null}export function parseIntent(t,e){const n=(t||"").trim().toLowerCase(),r=(void 0!==e?e:t||"").trim().toLowerCase();if(!n)return{intent:INTENTS.QA_FALLBACK,slots:{},confidence:0};if(includesAny(n,["speak in","speak to me in","switch to","change language to","talk to me in"])){const t=findLanguageTarget(n);if(t)return{intent:INTENTS.LANGUAGE_SWITCH,slots:{language:t},confidence:.9}}if(includesAny(n,["plan a trip","plan a","itinerary","build me a trip"])){const t=extractDays(n),e=extractAfter(n,["trip to ","itinerary for ","trip for "]);return{intent:INTENTS.ITINERARY,slots:{destination:e,days:t},confidence:e?.85:.5}}if(includesAny(r,["bookmark this","save this","add this to my journey","remember this place","bookmark it"])||n.includes("bookmark"))return{intent:INTENTS.BOOKMARK,slots:{},confidence:.9};if(includesAny(n,["search for ","find ","look up "])){const t=extractAfter(n,["search for ","look up ","find "]);if(t)return{intent:INTENTS.SEARCH,slots:{query:t},confidence:.8}}if(includesAny(n,["go to ","open ","take me to ","navigate to ","show me the "])){const t=findNavigationTarget(n);if(t)return{intent:INTENTS.NAVIGATE,slots:{target:t},confidence:.85}}return{intent:INTENTS.QA_FALLBACK,slots:{},confidence:0}}export default parseIntent;